# IR: {"sets":{"A":[0,1,2,3],"P":[[0,1],[0,2],[0,3],[1,2],[1,3],[2,3]],"C":"Distinct feasible stationary points of all faces, generated by nonsingular KKT systems with budget equality and up to three active bound/return inequalities"},"params":["expected_returns","variances","covariances","min_return","budget_fraction","max_asset_weight"],"derived":{"Q":"Symmetric covariance matrix from variances and covariances","v[c]":"c^T Q c"},"variables":{"w[a]":"continuous, 0 <= w[a] <= max_asset_weight","z[c]":"binary"},"constraints":["sum(c in C, z[c]) = 1","w[a] = sum(c in C, c[a]*z[c]) for each a","sum(a in A, w[a]) = budget_fraction","sum(a in A, expected_returns[a]*w[a]) >= min_return"],"objective":"minimize sum(c in C, v[c]*z[c])"}
#
# The APPSI HiGHS interface requires a linear objective. This script
# therefore uses an exact finite reformulation of the four-asset QP.
# Every global minimum of a quadratic over a nonempty bounded polytope
# has a representative among the face-stationary candidates below.
# Exact rational arithmetic avoids tolerances during candidate generation.

from fractions import Fraction
from itertools import combinations

import pyomo.environ as pyo
from pyomo.contrib.appsi.solvers.highs import Highs


def _as_fraction(value):
    return Fraction(str(value))


def _solve_linear_system(matrix, rhs):
    """Solve a square rational system; return None if singular."""
    size = len(rhs)
    augmented = [
        list(matrix[row_index]) + [rhs[row_index]]
        for row_index in range(size)
    ]

    for column_index in range(size):
        pivot_index = next(
            (
                row_index
                for row_index in range(column_index, size)
                if augmented[row_index][column_index] != 0
            ),
            None,
        )
        if pivot_index is None:
            return None

        augmented[column_index], augmented[pivot_index] = (
            augmented[pivot_index],
            augmented[column_index],
        )

        pivot = augmented[column_index][column_index]
        augmented[column_index] = [
            entry / pivot for entry in augmented[column_index]
        ]

        for row_index in range(size):
            if row_index == column_index:
                continue
            multiplier = augmented[row_index][column_index]
            if multiplier != 0:
                augmented[row_index] = [
                    augmented[row_index][entry_index]
                    - multiplier * augmented[column_index][entry_index]
                    for entry_index in range(size + 1)
                ]

    return [augmented[row_index][-1] for row_index in range(size)]


def _generate_candidates(covariance, returns, required_return, budget, cap):
    asset_count = len(returns)
    zero = Fraction(0)
    one = Fraction(1)

    # Each pair is the coefficient row and RHS when an inequality
    # is active. Multiplier signs are unnecessary because every
    # resulting candidate is checked against all primal constraints.
    potential_active_rows = []
    for asset_index in range(asset_count):
        unit_row = [
            one if entry_index == asset_index else zero
            for entry_index in range(asset_count)
        ]
        potential_active_rows.append((unit_row, zero))
        potential_active_rows.append((unit_row, cap))
    potential_active_rows.append((list(returns), required_return))

    candidates = set()

    for active_count in range(asset_count):
        for active_indices in combinations(
            range(len(potential_active_rows)), active_count
        ):
            equality_rows = [[one] * asset_count]
            equality_rhs = [budget]

            for active_index in active_indices:
                coefficients, rhs_value = potential_active_rows[active_index]
                equality_rows.append(coefficients)
                equality_rhs.append(rhs_value)

            equality_count = len(equality_rows)

            # KKT system:
            # [2Q  A^T] [w     ] = [0]
            # [A    0 ] [lambda]   [b]
            kkt_matrix = []
            for asset_index in range(asset_count):
                kkt_matrix.append(
                    [
                        2 * covariance[asset_index][other_index]
                        for other_index in range(asset_count)
                    ]
                    + [
                        equality_rows[row_index][asset_index]
                        for row_index in range(equality_count)
                    ]
                )

            for row_index in range(equality_count):
                kkt_matrix.append(
                    list(equality_rows[row_index])
                    + [zero] * equality_count
                )

            solution = _solve_linear_system(
                kkt_matrix,
                [zero] * asset_count + equality_rhs,
            )
            if solution is None:
                continue

            weights = tuple(solution[:asset_count])
            if any(weight < zero or weight > cap for weight in weights):
                continue
            if sum(weights, zero) != budget:
                continue
            portfolio_return = sum(
                (
                    returns[asset_index] * weights[asset_index]
                    for asset_index in range(asset_count)
                ),
                zero,
            )
            if portfolio_return < required_return:
                continue

            candidates.add(weights)

    return sorted(candidates)


def solve(params):
    asset_ids = tuple(range(4))
    asset_pairs = ((0, 1), (0, 2), (0, 3), (1, 2), (1, 3), (2, 3))

    expected_returns = tuple(
        _as_fraction(value) for value in params["expected_returns"]
    )
    variances = tuple(
        _as_fraction(value) for value in params["variances"]
    )
    covariances = tuple(
        _as_fraction(value) for value in params["covariances"]
    )
    min_return = _as_fraction(params["min_return"])
    budget_fraction = _as_fraction(params["budget_fraction"])
    max_asset_weight = _as_fraction(params["max_asset_weight"])

    if len(expected_returns) != len(asset_ids):
        raise ValueError("expected_returns must contain four values.")
    if len(variances) != len(asset_ids):
        raise ValueError("variances must contain four values.")
    if len(covariances) != len(asset_pairs):
        raise ValueError("covariances must contain six values.")

    covariance_matrix = [
        [Fraction(0) for _ in asset_ids] for _ in asset_ids
    ]
    for asset_index in asset_ids:
        covariance_matrix[asset_index][asset_index] = variances[asset_index]
    for (first_asset, second_asset), covariance in zip(
        asset_pairs, covariances
    ):
        covariance_matrix[first_asset][second_asset] = covariance
        covariance_matrix[second_asset][first_asset] = covariance

    candidates = _generate_candidates(
        covariance_matrix,
        expected_returns,
        min_return,
        budget_fraction,
        max_asset_weight,
    )

    # A nonempty bounded feasible polytope always contributes candidates.
    if not candidates:
        return {"objective": None, "status": "infeasible"}

    candidate_variances = [
        sum(
            (
                weights[first_asset]
                * covariance_matrix[first_asset][second_asset]
                * weights[second_asset]
                for first_asset in asset_ids
                for second_asset in asset_ids
            ),
            Fraction(0),
        )
        for weights in candidates
    ]

    model = pyo.ConcreteModel()
    model.asset_ids = pyo.Set(initialize=asset_ids, ordered=True)
    model.candidate_ids = pyo.Set(
        initialize=range(len(candidates)), ordered=True
    )

    model.asset_weight = pyo.Var(
        model.asset_ids,
        domain=pyo.NonNegativeReals,
        bounds=(0, float(max_asset_weight)),
    )
    model.candidate_selected = pyo.Var(
        model.candidate_ids,
        domain=pyo.Binary,
    )

    model.choose_candidate = pyo.Constraint(
        expr=sum(
            model.candidate_selected[candidate_index]
            for candidate_index in model.candidate_ids
        ) == 1
    )

    def link_weight_rule(instance, asset_index):
        return instance.asset_weight[asset_index] == sum(
            float(candidates[candidate_index][asset_index])
            * instance.candidate_selected[candidate_index]
            for candidate_index in instance.candidate_ids
        )

    model.link_weights = pyo.Constraint(
        model.asset_ids, rule=link_weight_rule
    )

    model.fully_invested = pyo.Constraint(
        expr=sum(
            model.asset_weight[asset_index] for asset_index in model.asset_ids
        ) == float(budget_fraction)
    )
    model.required_return = pyo.Constraint(
        expr=sum(
            float(expected_returns[asset_index])
            * model.asset_weight[asset_index]
            for asset_index in model.asset_ids
        ) >= float(min_return)
    )

    model.portfolio_variance = pyo.Objective(
        expr=sum(
            float(candidate_variances[candidate_index])
            * model.candidate_selected[candidate_index]
            for candidate_index in model.candidate_ids
        ),
        sense=pyo.minimize,
    )

    try:
        Highs().solve(model)
    except RuntimeError:
        return {"objective": None, "status": "solve_failed"}

    try:
        obj_val = float(pyo.value(model.portfolio_variance))
    except (ValueError, TypeError):
        return {"objective": None, "status": "objective_unavailable"}

    return {"objective": obj_val, "status": "optimal"}